def optimize_play(binary_str):
    n = len(binary_str)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for left in range(n - length + 1):
            right = left + length - 1
            if binary_str[left] == '0' and binary_str[right] == '1':
                dp[left][right] = max(dp[left + 1][right] + 1, dp[left][right - 1] + 1, dp[left + 1][right - 1] + 2)

    return dp[0][n-1]

