from collections import defaultdict

def merge_stacks(stacks, L):
    remained = stacks.pop()  # No stack is empty here.
    if L == remained[1]:
        return remained
    elif L >= remained[1]:
        nextstack1 = defaultdict(set)
        v, p = remained
        for u, vset in nextstack1.items():
            nextstack1[u] = vset | ((p := remained[0]) | (u := u ^ p))[:L-1]
        nextstack2 = defaultdict(set)
        for u, vset in nextstack2.items():
            nextstack2[u] = vset | (p := remained[0])[:L-1]
        return (v, L - remained[1]), nextstack1, nextstack2
    else:
        nextstack = defaultdict(set)
        for u, vset in stacks:
            u_childs = []
            for child in nextstack.items():
                child |= (u := u ^ (child[0] := remained[0]))[:L - 1]
                u_childs.append((u, child))
                nextstack[u] = nextstack[u] | set(child)
            nextstack[u] |= vset | u_childs
        return nextstack

def merge(a, b, L):
    nextstack = defaultdict(set)
    for u, v in a.keys():
        c = v - a[u]
        if L == a[u][1]:
            nextstack[v] = nextstack[v] | c
        elif L > c:
            nextstack[v] = nextstack[v] | (a[u][0] | (u := u ^ (a[u][0]))[:L-1])
    v, _ = maxnextstacks(v)
    for u in nextstack:
        v |= nextstack[u] ^ v
        nextstack[u] = set()
    return v, v

def maxnextstacks(v):
    nextstack1 = defaultdict(set)
    for u in v:
        u_childs = []
        if u in v:
            for child in nextstack1.items():
                child |= (u := u ^ (child[0] := v[u][0]))[:1]
                nextstack1[u] = child
            v[u] |= u_childs
    nextstack2 = defaultdict(set)
    for u in v:
        v_childs = []
        if u in v:
            child = (v[x][0] := u) for x in nextstack2.items()
            for child in nextstack2.items():
                child |= (u := child[0] ^ (child[0] := u ^ child[1]))[:1]
                nextstack2[u] = set(child)
        v[u] |= v_childs
    return v, nextstack1, nextstack2

