def reconstruct_edges(visited, edges, graph):
    path = []
    for edge in edges:
        if not visited[edge[0] - 1]:
            path.append(edge[0])
            visited[edge[0] - 1] = True
        if not visited[edge[1] - 1]:
            path.append(edge[1])
            visited[edge[1] - 1] = True
    return path

def walk_tree(visited, edges, start, graph):
    visited[start - 1] = True
    path = [start]
    while True:
        new_path = []
        for edge in edges:
            if edge[0] == start - 1:
