from itertools import permutations

def find_smallest_sequence(N, K, A):
    arrangements = {}
    for perm in permutations(A):
        non_decreasing_subsequence_length = 1
        previous_element = perm[0]
        for element in perm[1:]:
            if element >= previous_element:
                non_decreasing_subsequence_length += 1
            else:
                non_decreasing_subsequence_length = 1
            if non_decreasing_subsequence_length <= K:
                arrangements[perm] = non_decreasing_subsequence_length
            previous_element = element

    if K in arrangements:
        return ' '.join(map(str, arrangements[K]))
    else:
        return "-1"

def solve_testcase(N, K, A):
    return find_smallest_sequence(N, K, A)

