import sys

def count_fishes_in_interval(fish_positions: List[int], start: int, end: int) -> int:
    if start < 0:
        start = 0
    left = max(0, start - len(fish_positions))
    right = min(len(fish_positions), end - 1 + 1)
    return sum(fish_positions[left:right+1])

def min_flips_required(target_seconds: int, cutlet_length: int, start: int, end: int) -> int:
    left, right = min(cutlet_length, target_seconds - start), max(0, target_seconds - end)
    if right == 0:
        return 0
    return target_seconds - start + end - 1

def can_fry_cutlet(n: int, k: int, periods: List[Tuple[int, int]]) -> bool:
    fish_positions = [i for i in range(n*2 + 1)]
    for start, end in periods:
        fish_positions[start] += 1
        fish_positions[end] -= 1
    max_count = max(count_fishes_in_interval(fish_positions, 0, i) for i in range(n))
    min_flips = min_flips_required(n, len(fish_positions), max_count, max(n - max_count + 1, 0))
    if n - max_count < min_flips:
        return False
    return True, min_flips

