import math

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_consecutive(prime, numbers):
    """Count the number of consecutive numbered cards to flip."""
    count = 0
    for i in range(len(numbers) - (prime - 1)):
        if is_prime(numbers[i + (prime - 1)]) and (
            numbers[i + (prime - 1)] <= numbers[i]
            or is_prime(numbers[i + (prime - 1)])
        ):
            count += 1
    return count

def min_operations(N, numbers):
    """Calculate the minimum operations needed to make all cards face down."""
    total_chips = set(numbers)
    if len(total_chips) == 1:
        return count_consecutive(1, numbers)

    prime_factors = {}
    for p in prime_factors:
        if prime_factors[p] <= len(numbers) // p:
            continue
        prime_factors[p] = 0
    total_operations = float('inf')

    for p in prime_factors:
        if p == 1:
            continue
        prime_factors[p] += total_consecutive(p, numbers)

    for p in prime_factors:
        if total_consecutive(p, numbers) < total_operations:
            total_operations = min(total_consecutive(p, numbers), total_operations)
        prime_factors[p] -= total_consecutive(p, numbers)

    return total_operations

def total_consecutive(prime, numbers):
    """Count the total number of consecutive cards to flip for a prime number."""
    consecutive_numbers = set()
    for i in range(-1, len(numbers) - prime + 2):
        consecutive_numbers.add(numbers[i])
    consecutive_numbers = sorted(consecutive_numbers)
    consecutive_length = len(consecutive_numbers)

    if consecutive_length % prime != 0:
        consecutive_length -= (consecutive_length % prime)
        if consecutive_length % prime == 1:
            consecutive_length -= 1

    flip_count = 0
    for i in range(0, len(consecutive_numbers), prime):
        flip_count += sum(1 for j in range(i, i + prime) if consecutive_numbers[j] == consecutive_numbers[i])

    return flip_count

def main():
    N = int(input())
    numbers = list(map(int, input().split()))
    result = min_operations(N, numbers)
    print(result)

if __name__ == "__main__":
    main()
