from math import gcd

def gcd_exponential(a, b):
    return (a if b == 0 else gcd_exponential(b, a % b))

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_minimum_flips(num_cards, cards):
    num_twos = sum(True for i in range(num_cards) if cards[i] % 2 == 0)
    gcd_val = gcd_exponential(num_twos, num_cards - num_twos)

    def cost_per_flip(p):
        return sum(True for i in range(p) if cards[i] % 2 == 0)

    num_flips = 0
    for p in range(3, num_cards + 1):
        if gcd(p, num_cards) - 1 > gcd_val:
            continue
        if is_prime(p):
            for flip in range(p, num_cards + 1, p - flip):
                if cost_per_flip(flip) != gcd_val // num_twos:
                    break
                num_flips += flip

    # Note: we have assumed that p and q are coprime!
    #         i.e. gcd(p, q) = 1
    #         we can prove by contradiction and p and q are not both odd!
    return num_flips - num_twos // gcd_val

