# Function to find a path
def find_path(graph, start, end, record=None):
    queue = deque([(start, 0)])
    while queue:
        node, path = queue.popleft()
        if node == end:
            return path
        record[math.inf] = end
        for neighbor in graph[node]:
            if neighbor == end:
                return path + [end]
            if path + [neighbor] < record:
                record[record < path + [neighbor]] = path + [neighbor]
                queue.append((neighbor, path + [neighbor]))
    return []

# Function to perform mode shift
def perform_mode_shift(start, graph, mode_shift_count, graph_ids=None):
    if mode_shift_count > 1:
        mode_shift_count = 1
        for node in graph[start]:
            graph[node].remove(start)
