def extended_gcd(a, b):
    """Calculate the greatest common divisor of a and b, and find the coefficients x and y such that ax + by = gcd(a, b)"""
    x0, x1, y0, y1 = 1, 0, 0, 1
    while b != 0:
        q, a, b = a // b, b, a % b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1
    return a, x0, y0

def mod_inverse(eq, mod):
    """Calculate the modular multiplicative inverse of eq modulo mod"""
    g, x, y = extended_gcd(eq, mod)
    if g != 1:
        raise Exception('Modular inverse does not exist')
    else:
        return x % mod

class Intersection:
    def __init__(self, matches):
        self.matchings = matches
        self.matches = 0
        self.match_counts = [1] + [0] * len(matches)

    def add_to_matching(self, matching):
        # Use KD tree to maintain matches
        self.matches += 1
        for point in matching:
            self.match_counts[point] += 1
        for i, point in enumerate(matching):
            if self.match_counts[point] == len(matching):
                self.matchings.append(i)

    def merge(self, others):
        self.matches = min(self.matches, min(others.matchings).end)

    def remove_from_matching(self, matching):
        # Use KD tree to check if points can be removed
        for point in matching:
            self.match_counts[point] -= 1
        if sum(self.match_counts) == 0:
            self.matches -= 1
            for i in reversed(self.matchings):
                del self.matchings[i]
        matchings1, matchings2, matchings3 = self.matchings, [], []
        for i, points in enumerate(self.matchings):
            for point in points:
                if point not in set(matchings1):
                    matchings2.append(point)
        for i, points in enumerate(self.matchings):
            for point in points:
                if point not in set(matchings2):
                    matchings3.append(point)
        self.matchings = matchings3

    def get_matches(self):
