        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

# Function to flip cards from index i to index j with step size p
def flip_cards(cards, i, j, p):
    flipped = 0
    for k in range(i, j+1, p):
        if cards[k-1] % 2 == 0:
            cards[k-1] += 1
            flipped += 1
        if cards[k-1] % 2 == 1:
            cards[k-1] += 1
            flipped += 1
    return flipped

# Function to find the minimum number of flips required
def min_flips(cards):
    p = 2
    while True:
        if all(card % 2 == 0 for card in cards):
            return 0
        for i in range(len(cards)):
            if any(j + i for j in range(len(cards))) % p == 0:
                flipped = flip_cards(cards, i, len(cards), p)
                if flipped < len(cards):
                    cards = cards[:i] + [2 * card - 1 for card in cards[i:]] + cards[i:]

        if not p <= gcd([p, 2]):
            break
        p += 1

    # If not all cards are flipped to face down, flip all remaining cards
    return sum(cards)

