import math

def min_distance(n, k, points):
    # Iterate through each line parallel to x-axis (where y coordinates are same)
    for y in range(-10**6, 10**6 + 1):
        line = []  # List of points on the line
        for x, x2, y in points:
            if y == y2:  # Check if the point lies on the current line
                line.append((x, x2))
            else:
                line.append((x, [x2, x - x2, y, y2].pop()))
        # Use the Sieve of Eratosthenes to find the minimum distance between points on the line
        dist_map = {}
        for i in range(1, len(line)):
            dist = abs(line[i][0] - line[0][0])
            if line[i][1] not in dist_map:
                dist_map[line[i][1]] = dist
            else:
                dist_map[line[i][1]] = min(dist_map[line[i][1]], dist)
        # Calculate the minimum distance to visit all points
        for xi, x2 in enumerate(abs(line)):
            dist_map[x2[1]] = min(dist_map[x2[1]], dist_map[x2[1]] - line[0][0])
        result = [dist_map[number] if number in dist_map else math.inf for number in range(-10**6, 10**6 // 2 + 1)]
        return 0 if math.isinf(abs(result[-1])) else abs(result[-1])

