def find_optimal_distribution(n, budget, marks):
    if n * 5 > budget:
        return -1
    if n * 3 > budget:
        return -1

    k5 = budget // 5
    if k5 * 5 != budget:
        k5 -= 1

    k4 = min(k5, budget - k5 * 5) // 4
    if k4 * 4 != budget - k5 * 5:
        k4 -= 1

    k3 = budget - k4 * 4 - k5 * 5

    return k3, k4, k5

