def find_smallest_sequence(A, K):
    freq = defaultdict(int)
    for num in A:
        freq[num] += 1

    max_freq = max(freq.values())
    sequence = []
    for i in range(len(A)):
        if freq[A[i]] == max_freq:
            sequence.append(A[i])
            for j in range(i + 1, len(A)):
                if freq[A[j]] == max_freq:
                    sequence.append(A[j])
                    break
            break

    if len(sequence) < K:
        return -1
    if len(sequence) == K:
        return ' '.join(map(str, sequence))
    return ' '.join(map(str, sequence[:K]) + ['-1'] * (len(sequence) - K))

