def next_bigger(nums):
    stack = deque()
    next_bigger_array = [-1] * len(nums)

    for i in range(len(nums) - 1, -1, -1):
        while stack and nums[i] <= stack[-1]:
            stack.pop()
        if stack:
            next_bigger_array[i] = stack[-1]
        stack.append(nums[i])

    return next_bigger_array

def construct_bisubsequence(A, K):
    N = len(A)
    A.sort()

    for K in range(1, N + 1):
        for perm in permutations(A):
            if len(set(perm)) <= K:
                continue
            if max(set(perm)) - min(set(perm)) == K:
                if len(perm) >= K:
                    A = perm
                    break
        if len(A) >= K:
            continue
        if next_bigger(A):
            return '-1'
        else:
            return ''.join([str(i) for i in A])

    return '-1'

