def calculate_min_roads(N, A):
    total_length = 0

    # Create a mask array for all bitwise AND with L
    mask_array = [0] * (2 ** N)
    for i in range(N):
        for j in range(N):
            bitwise_and = A[i] & A[j]
            if bitwise_and != 0 and bitwise_and <= 2 ** N:
                mask_array[bitwise_and] += 1

    # Traverse the mask array to find the minimum length
    for i in range(1, 2 ** N):
        if mask_array[i] % 2 != 0:
            return -1

    for i in range(1, 2 ** N):
        if mask_array[i] % 2 == 1:
            total_length += i

    return total_length

