import sys

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

def get_distance(p1, p2):
    return (p1.x - p2.x) ** 2 + (p1.y - p2.y) ** 2 ** 0.5

def manhattan_distance(p1, p2):
    return abs(p1.x - p2.x) + abs(p1.y - p2.y)

def heuristic(start, goal):
    # Simplified Manhattan heuristic for the start point
    return manhattan_distance(start, goal)

def dijkstra(start, goal, all_points):
    # A* search, considering the heuristic
    open_set = [(manhattan_distance(start, goal), 0, start)]
    visited = [False] * len(all_points)
    while open_set:
        f, g, current = heapq.heappop(open_set)
        if visited.index(current):
            continue
        visited[current] = True
        if current == goal:
            return g
        for neighbor in range(len(all_points)):
            if not visited[neighbor] and get_distance(all_points[neighbor], current) <= 1:
                heapq.heappush(open_set, (f + heuristic(all_points[neighbor], current) + get_distance(all_points[neighbor], neighbor), g + 1, neighbor))

def farthest_sonar(point, nav_points, k):
    nav_points.sort(key=lambda p: get_distance(point, p))
    sonar = {point}
    for _ in range(k - 1):
        sonar -= {nav_points.pop()}
    return sonar

