from math import comb

mod = 10**9 + 7

def npotient(n, k):
    assert 1 <= n <= 10**9 and 1 <= k <= 5000
    if n == 1:
        return 1
    if k == 1:
        return mod + n * (mod-1)
    if k == 2:
        return mod + n * (mod**2 - n)
    # Implement leading terms for powers of x^k
    leading_term = 1
    for i in range(k-3, -1, -1):
        leading_term = (n * comb(n, i)) % mod
    return (leading_term + n * (mod**k - leading_term)) % mod

