            for v in graph[u]:
                if v in cycle and graph[u][v] != u and graph[u][v] != v:
                    cycle_pairs += 1
        if len(cycle) * 2 < n_pairs * (n_pairs - 1) or n_pairs * 2 < len(cycle) * 2:
