                        return True
        return False

def CycleCycleMatch(n_nodes, n_pairs, cycle, graph):
    cycle_set = set(cycle)
    possible_pairs = []
    for u in cycle:
        for v in graph[u]:
            if v in cycle_set:
                possible_pairs.append((u, v))
    if len(possible_pairs) <= n_pairs:
        return True
    q = [x for x in possible_pairs]
    while q:
        u, v = q.pop()
        if u in cycle_set and v in cycle_set and graph[u][v] in cycle:
            return True
        if u not in cycle_set:
            q.insert(0, v)
        if v not in cycle_set:
            q.insert(0, u)
    return False

def get_valid_pairs(n_pairs, n_nodes, cycle, graph):
    pairs = []
    for u in cycle:
        for v in graph[u]:
            if graph[u][v] not in cycle and graph[u][v] in cycle_set:
                pairs.append((u, v))
    return pairs

