    edge_info = defaultdict(set)
    for u, v in edges:
        edge_info[u].add(v)
        edge_info[v].add(u)

    pairings = []
    visited = set()
    for node, neighbors in edge_info.items():
        if not visited & neighbors:
            for neighbor in neighbors:
                visited.add(node)
                visited.add(neighbor)
                path = {min(node, neighbor), max(node, neighbor)}
                new_neighbors = neighbors - path
                new_edges = set(
                    [(u, v) for u in path for v in new_neighbors]
                )
                new_pairings = pairings + get_pairings(m - len(path), new_edges)
                if not new_pairings:
                    pairings += [(node, neighbor)]
                    visited.remove(node)
                    visited.remove(neighbor)
                    break
    return pairings

def get_pairings(m, edges):
    if m < 4:
        return []
    pairings = []
    pairs = nlargest(4, edge_info, key=lambda x: len(edge_info[x]))
    for pair in pairs:
        u, v = pair
        new_edges = set((u, x) for x in edge_info[u] if x != v) | set((v, x) for x in edge_info[v] if x != u)
        new_pairings = get_pairings(m - len(pair), new_edges)
        if not new_pairings:
            continue
        for p1, p2 in new_pairings:
            p3, p4 = [edge for edge in edges if edge != (u, v) and edge != (p1, p2)][0]
            pairings.append((u, v, p1, p2, p3, p4))
