def find_path_or_pairing(graph: dict, nodes: Sequence[int], max_pairs: int) -> Iterator[tuple]:
    if len(nodes) <= max_pairs:
        yield (nodes, max_pairs)
    else:
        for pair in itertools.combinations(nodes, max_pairs):
            if check_valid_pairing(graph, [pair]):
                yield (pair, max_pairs)
        for u in nodes:
            new_nodes = list(nodes)
            new_nodes.remove(u)
            for pair in find_path_or_pairing(graph, tuple(new_nodes), max_pairs):
                yield (u, *pair)


