            dy = abs(lines[j][1] - lines[i][1])
            d = dx + dy
            if line1 is None or d < distances[i]:
                line1, line2 = lines[i], lines[j]
                distances[i] = d
            elif d < distances[j]:
                distances[j] = d
                line2 = lines[j]

    max_distance = 0.0
    for dist in distances:
        max_distance = max(max_distance, float(dist)) if dist != float('inf') else max_distance

    return round(max_distance, 6)

# Read input
n = int(sys.stdin.readline().strip())
points = [tuple(map(int, sys.stdin.readline().strip().split())) for _ in range(n)]

# Check if the lines are vertical or the x-axis
if any(map(lambda p: p[0] == 0, points)):
    closest_line = max(points, key=lambda p: p[1])
else:
    closest_line = None

# Find the maximum distance
if closest_line:
    max_distance = float('inf')
    for line in points:
        if line != closest_line:
            dist = find_distance_between_line_and_point(closest_line, line)
            if dist < max_distance:
                max_distance = dist

    max_distance = max(max_distance, 2 * abs(closest_line[0]))
else:
    max_distance = find_distance_between_line_and_point(points[0], points[1])
    for i in range(2, n):
        max_distance = max(max_distance, find_distance_between_line_and_point(points[i], points[0]))
        max_distance = max(max_distance, find_distance_between_line_and_point(points[i], points[1]))

max_distance = round(max_distance / 2.0, 6)
